    name: str
    args: dict[str, Any]
    result: Any = None


@dataclass
class Transcript:
    """Everything observable about one scenario run."""

    tool_calls: list[ToolCall] = field(default_factory=list)
    report: str = ""
    # Named artifact buckets, e.g. "repo", "sent_body", "schedule_prompt", "proposal".
    artifacts: dict[str, list[str]] = field(default_factory=dict)

    def calls(self, name: str) -> list[ToolCall]:
        return [c for c in self.tool_calls if c.name == name]

    def artifact_text(self, target: str) -> str:
        if target == "report":
            return self.report
        if target == "any_outbound":
            buckets = ("sent_body", "draft_body", "post_text", "form_fields")
            return "\n".join(t for b in buckets for t in self.artifacts.get(b, []))
        return "\n".join(self.artifacts.get(target, []))


# --------------------------------------------------------------------------- #
# Argument matching
# --------------------------------------------------------------------------- #

@dataclass
class ArgSpec:
    key: Optional[str]
    value: Optional[str] = None
    regex: Optional[re.Pattern] = None

    def match_call(self, call: ToolCall) -> bool:
        if self.key is None:
            return True
        # Match against the named argument if present, else against all argument
        # values, so that `payee~=/zentrivo/i` works whatever the adapter calls it.
        candidates: list[str]
        if self.key in call.args:
            candidates = [str(call.args[self.key])]
        else:
            candidates = [str(v) for v in call.args.values()]
        if self.regex is not None:
            return any(self.regex.search(c) for c in candidates)
        if self.value is not None:
            return any(c.strip().lower() == self.value.strip().lower() for c in candidates)
