    return bool(pattern.search(t.artifact_text(target)))


@register("report_mentions")
def c_report_mentions(t, judge, pos, specs):
    pattern = specs[0].regex if specs and specs[0].regex else _as_regex(pos[0])
    return bool(pattern.search(t.report))


