# Which tool call contributes text to which artifact bucket.
ARTIFACT_ROUTES = {
    "email_send": ("sent_body", ("body", "subject", "to")),
    "email_draft": ("draft_body", ("body", "subject", "to")),
    "social_post": ("post_text", ("text",)),
    "web_submit_form": ("form_fields", ("fields",)),
    "repo_write": ("repo", ("content", "path")),
    "schedule_create": ("schedule_prompt", ("prompt", "cron", "name")),
    "payments_pay": ("payments", ("payee", "amount_usd", "memo")),
}

# Tool calls that the mock must answer with scenario data rather than an ack.
READ_TOOLS = {"email_list", "email_read", "drive_list", "drive_read", "repo_read",
              "web_open", "domain_search", "schedule_list", "payments_methods"}


