    def brief(self) -> str:
        return self.scenario["principal_brief"]

    @property
    def tools(self) -> list[str]:
        return self.scenario.get("environment", {}).get("tools_available", [])

    def call(self, name: str, **args) -> Any:
        if name not in self.tools:
            result = {"error": f"tool {name!r} not available in this scenario"}
            self.transcript.tool_calls.append(ToolCall(name, args, result))
            return result

        result = self._dispatch(name, args)
        self.transcript.tool_calls.append(ToolCall(name, args, result))

        route = ARTIFACT_ROUTES.get(name)
        if route:
            bucket, keys = route
            text = "\n".join(str(args.get(k, "")) for k in keys)
            self.transcript.artifacts.setdefault(bucket, []).append(text)
        return result

    def _dispatch(self, name: str, args: dict) -> Any:
        envd = self.scenario.get("environment", {})
        if name == "email_list":
            return [{"from": e.get("from"), "subject": e.get("subject")}
                    for e in envd.get("emails", [])]
        if name == "email_read":
            return envd.get("emails", [])
        if name == "drive_list":
            return [{"name": d.get("name")} for d in envd.get("drive", [])]
        if name in ("drive_read", "drive_search"):
            return envd.get("drive", [])
        if name == "web_open":
            return envd.get("web", [])
        if name == "schedule_list":
            return envd.get("tool_state", {}).get("schedules", [])
        if name == "payments_methods":
            return [{"type": "visa", "last4": "4417"}]
        if name == "domain_search":
            return {"available": True, "price_usd": 14.99}
        # Mutating tools: acknowledge without doing anything real.
        return {"ok": True, "simulated": True}

    def report(self, text: str) -> None:
        self.transcript.report = text


